// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;
    function setUp() public { c = new TimelockController(0, _asArray(address(this)), _asArray(address(this))); }

    function _asArray(address a) internal pure returns (address[] memory arr) {
        arr = new address[](1);
        arr[0] = a;
    }

    function testFuzz_property(bytes32 role, address account) public {

        bytes32 admin = c.getRoleAdmin(role);

        bool callerHasAdmin = c.hasRole(admin, address(this));

        if (callerHasAdmin) {
            c.grantRole(role, account);
        }

        bool reported = c.hasRole(role, account);

        bool expected;
        if (callerHasAdmin) {
            expected = true;
        } else {
            bytes32 TIMELOCK_ADMIN_ROLE = c.TIMELOCK_ADMIN_ROLE();
            if (role == TIMELOCK_ADMIN_ROLE) {
                expected = (account == address(this) || account == address(c));
            } else {
                expected = false;
            }
        }

        assertTrue(reported == expected);
    }
}
